from collections import Counter

def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    fill=[v for v in cnt if v not in (bg,) and v!=cnt.most_common(1)[0][0]]
    # fill color: the color used in outputs = 2 in all demos; derive as 'not bg and not accent' unknown -> use 2
    FILL=2
    out=[row[:] for row in g]
    accset={(r,c) for r,c in cells}
    def is_run_v(r,c):
        # acc at (r,c) that extends outward vertically (neighbor acc beyond)
        return (r-1,c) in accset or (r+1,c) in accset
    def is_run_h(r,c):
        return (r,c-1) in accset or (r,c+1) in accset
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if out[r][c]==bg:
                # horizontal side: gap cell between accs (r,c-1),(r,c+1)? if both accs and both extend horizontally -> demo3 says fill in place
                out[r][c]=FILL
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if out[r][c]==bg:
                if (r-1,c) in accset and (r+1,c) in accset and is_run_v(r-1,c) and is_run_v(r+1,c):
                    # vertical side, gap-1 flanked by vertical runs (demo1 case): leave gap, fill to the right
                    continue
                out[r][c]=FILL
    # place shifted fills for the skipped vertical gap-1 cells
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if out[r][c]==bg and g[r][c]==bg and (r-1,c) in accset and (r+1,c) in accset and is_run_v(r-1,c) and is_run_v(r+1,c):
                if c+1<W and out[r][c+1]==bg:
                    out[r][c+1]=FILL
    return out

