def capS(g, T=6):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    accs={(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg}
    out=[row[:] for row in g]
    for r in range(H):
        row=sorted(c for c in range(W) if (r,c) in accs)
        for a,b in zip(row,row[1:]):
            if b-a-1<=T:
                for c in range(a+1,b): out[r][c]=2
    for c in range(W):
        col=sorted(r for r in range(H) if (r,c) in accs)
        for a,b in zip(col,col[1:]):
            if b-a-1<=T:
                for r in range(a+1,b): out[r][c]=2
    return out
